<?php
namespace App\Http\Controllers; use App\Models\TeachingMaterial; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class MaterialController extends Controller { public function index(Request $r){$materials=TeachingMaterial::with('uploader')->when($r->search,fn($q,$v)=>$q->where('title','like',"%$v%"))->when($r->subject,fn($q,$v)=>$q->where('subject',$v))->when($r->grade,fn($q,$v)=>$q->where('grade',$v))->when($r->material_type,fn($q,$v)=>$q->where('material_type',$v))->latest('uploaded_at')->paginate(15)->withQueryString();return view('materials.index',compact('materials'));} public function create(){return view('materials.form');} public function store(Request $r){$d=$r->validate(['title'=>'required|string|max:255','description'=>'nullable|string','subject'=>'nullable|string|max:100','grade'=>'nullable|string|max:50','material_type'=>'nullable|string|max:50','file'=>'required|file|mimes:pdf,doc,docx,ppt,pptx,jpg,jpeg,png|max:20480']);$d['uploaded_by']=$r->user()->id;$d['uploaded_at']=now();$d['file_path']=$r->file('file')->store('materials');TeachingMaterial::create($d);return redirect()->route('materials.index')->with('success','Material uploaded successfully.');} public function show(TeachingMaterial $material){return view('materials.show',compact('material'));} public function download(TeachingMaterial $material){abort_unless(Storage::exists($material->file_path),404);return Storage::download($material->file_path);} public function destroy(TeachingMaterial $material){Storage::delete($material->file_path);$material->delete();return back()->with('success','Material deleted successfully.');}}
